import json, subprocess, sys, unittest
from upload import retry_upload

def queued():
    return {"pending": "photo.png", "uploaded": None, "status": "queued"}

class RetryUploadTimeoutTest(unittest.TestCase):
    def test_timeout_keeps_pending_attachment(self):
        s = retry_upload(queued(), "timeout")
        self.assertEqual(s, {"pending": "photo.png", "uploaded": None, "status": "timeout"})

    def test_retry_after_timeout_uploads_original_attachment(self):
        s = retry_upload(retry_upload(queued(), "timeout"), "ok")
        self.assertEqual(s, {"pending": None, "uploaded": "photo.png", "status": "uploaded"})

    def test_repeated_timeouts_keep_pending_attachment(self):
        s = queued()
        for _ in range(3):
            s = retry_upload(s, "timeout")
        self.assertEqual(s["pending"], "photo.png")

    def test_ok_clears_pending_after_upload(self):
        s = retry_upload(queued(), "ok")
        self.assertEqual(s, {"pending": None, "uploaded": "photo.png", "status": "uploaded"})

    def test_cli_timeout(self):
        out = subprocess.run([sys.executable, "upload.py", "timeout"], capture_output=True, text=True, check=True).stdout
        self.assertEqual(json.loads(out), {"pending": "photo.png", "uploaded": None, "status": "timeout"})

if __name__ == "__main__":
    unittest.main()
