import subprocess, sys, unittest
from editor import word_count

def draft(text):
    return {"draft": text, "saved": "", "status": "editing"}

class WordCountTest(unittest.TestCase):
    def test_single_word(self):
        self.assertEqual(word_count(draft("alpha")), 1)

    def test_empty_draft(self):
        self.assertEqual(word_count(draft("")), 0)

    def test_whitespace_only(self):
        self.assertEqual(word_count(draft("  \n\t ")), 0)

    def test_mixed_whitespace_and_punctuation(self):
        self.assertEqual(word_count(draft("  alpha,  beta\ngamma\tdelta. ")), 4)

    def test_does_not_mutate_state(self):
        s = draft("alpha beta")
        word_count(s)
        self.assertEqual(s, draft("alpha beta"))

    def test_cli_word_count(self):
        out = subprocess.run([sys.executable, "editor.py", "word-count"], capture_output=True, text=True, check=True).stdout
        self.assertEqual(out, "1\n")

if __name__ == "__main__":
    unittest.main()
